/* 「不再叠一份食材贴图」必须只看**盘位那一块**：底排食材桶每帧都要画 egg.png，
   整帧里数 egg.png 是数不准的。 */
const pbox3 = b5.B.plateBox(3);
const inPlate = (name) => b5.record.drawImage.some(r => r.src.split("/").pop() === name &&
  (r.dx + r.dw / 2) >= pbox3.x && (r.dx + r.dw / 2) <= pbox3.x + pbox3.w &&
  (r.dy + r.dh / 2) >= pbox3.y && (r.dy + r.dh / 2) <= pbox3.y + pbox3.h);
A(!inPlate("egg.png"), "盘贴图自带食物时，盘位框里不再叠一份食材贴图（避免一盘两样）",
  "盘位框 " + JSON.stringify(pbox3));
/* 反过来验一次：没有专属盘贴图的食材（白粥）→ 盘位仍是「空盘 + 食物贴图」 */
d5.drop("congee", null); d5.plateNow(0);
b5.record.drawImage.length = 0;
b5.pump(1);
const pbox0 = b5.B.plateBox(0);
A(b5.record.drawImage.some(r => r.src.split("/").pop() === "congee.png" &&
  (r.dx + r.dw / 2) >= pbox0.x && (r.dx + r.dw / 2) <= pbox0.x + pbox0.w &&
  (r.dy + r.dh / 2) >= pbox0.y && (r.dy + r.dh / 2) <= pbox0.y + pbox0.h),
  "白粥落盘 → 盘位是「plate_empty + 食物贴图」（没有专属盘贴图的食材照旧这样画）");

